  "Nuk lejohen pamje shqetësuese, eksplicite apo që shkelin privatësinë e personave të tretë pa miratimin e tyre. Përmbajtja vizuale duhet t'i shërbejë interesit publik.": {
    "sq": "Nuk lejohen pamje shqetësuese, eksplicite apo që shkelin privatësinë e personave të tretë pa miratimin e tyre. Përmbajtja vizuale duhet t'i shërbejë interesit publik.",
    "en": "Images that are disturbing, explicit or violate the privacy of third parties are not allowed without their approval. Visual content must serve the public interest.",
    "bs": "Slike koje uznemiravaju, eksplicitne ili narušavaju privatnost trećih lica nisu dozvoljene bez njihovog odobrenja. Vizuelni sadržaj mora služiti javnom interesu.",
    "sr": "Слике које узнемиравају, експлицитне или нарушавају приватност трећих лица нису дозвољене без њиховог одобрења. Визуелни садржај мора служити јавном интересу.",
    "tr": "Üçüncü şahısların rahatsız edici, müstehcen veya mahremiyetini ihlal eden görsellerin onların onayı olmadan yayınlanmasına izin verilmez. Görsel içerik kamu yararına hizmet etmelidir.",
    "de": "Bilder, die verstörend oder anstößig sind oder die Privatsphäre Dritter verletzen, sind ohne deren Zustimmung nicht gestattet. Visuelle Inhalte müssen dem öffentlichen Interesse dienen."
  },
  "Sistemi i Sanksioneve": {
    "sq": "Sistemi i Sanksioneve",
    "en": "System of Sanctions",
    "bs": "Sistem sankcija",
    "sr": "Систем санкција",
    "tr": "Yaptırım Sistemi",
    "de": "System der Sanktionen"
  },
  "Sistemi ynë i moderimit AI (Auto-Pilot) fshin automatikisht fjalët banale. Nëse një përdorues shkel kodin më shumë se 3 herë, llogaria e tij bllokohet (Banned) në mënyrë të pakthyeshme nga platforma.": {
    "sq": "Sistemi ynë i moderimit AI (Auto-Pilot) fshin automatikisht fjalët banale. Nëse një përdorues shkel kodin më shumë se 3 herë, llogaria e tij bllokohet (Banned) në mënyrë të pakthyeshme nga platforma.",
    "en": "Our AI (Auto-Pilot) moderation system automatically deletes banal words. If a user violates the code more than 3 times, his account is irrevocably banned from the platform.",
    "bs": "Naš AI (Auto-Pilot) sistem moderiranja automatski briše banalne riječi. Ako korisnik prekrši kod više od 3 puta, njegov račun je neopozivo zabranjen sa platforme.",
    "sr": "Наш систем модерације АИ (Ауто-Пилот) аутоматски брише баналне речи. Ако корисник прекрши код више од 3 пута, његов налог је неопозиво забрањен са платформе.",
    "tr": "Yapay Zeka (Otomatik Pilot) denetleme sistemimiz banal kelimeleri otomatik olarak siler. Bir kullanıcının kodu 3 defadan fazla ihlal etmesi durumunda hesabı geri dönülemez şekilde platformdan yasaklanır.",
    "de": "Unser KI-Moderationssystem (Auto-Pilot) löscht banale Wörter automatisch. Verstößt ein Nutzer mehr als dreimal gegen den Kodex, wird sein Account unwiderruflich von der Plattform gesperrt."
  },
  "Platforma jonë mbahet e gjallë falë sponsorizimeve nga bizneset lokale. Për të ruajtur transparencën, OÇDO reklamë apo përmbajtje e paguar shënjohet qartë me etiketën": {
    "sq": "Platforma jonë mbahet e gjallë falë sponsorizimeve nga bizneset lokale. Për të ruajtur transparencën, OÇDO reklamë apo përmbajtje e paguar shënjohet qartë me etiketën",
    "en": "Our platform is kept alive thanks to sponsorships from local businesses. To maintain transparency, ANY advertising or paid content is clearly labeled",
    "bs": "Naša platforma održava se na životu zahvaljujući sponzorstvima lokalnih preduzeća. Da bi se održala transparentnost, BILO KOJI reklamni ili plaćeni sadržaj je jasno označen",
    "sr": "Наша платформа се одржава у животу захваљујући спонзорствима локалних предузећа. Да би се одржала транспарентност, БИЛО КОЈИ рекламни или плаћени садржај је јасно означен",
    "tr": "Yerel işletmelerin sponsorlukları sayesinde platformumuz canlı tutuluyor. Şeffaflığı korumak için HERHANGİ BİR reklam veya ücretli içerik açıkça etiketlenir",
    "de": "Unsere Plattform wird dank Sponsoring lokaler Unternehmen am Leben gehalten. Um die Transparenz zu wahren, sind JEGLICHE Werbung oder kostenpflichtige Inhalte deutlich gekennzeichnet"
  },
