  "Algoritmet tona nuk manipulojnë \"Feed-in\" publik për të favorizuar pagesat ndaj përmbajtjes qytetare.": {
    "sq": "Algoritmet tona nuk manipulojnë \"Feed-in\" publik për të favorizuar pagesat ndaj përmbajtjes qytetare.",
    "en": "Our algorithms do not manipulate the public Feed to favor paid over civic content.",
    "bs": "Naši algoritmi ne manipulišu javnim Feed-om da bi davali prednost plaćenom u odnosu na građanski sadržaj.",
    "sr": "Наши алгоритми не манипулишу јавним Феед-ом да би давали предност плаћеном у односу на грађански садржај.",
    "tr": "Algoritmalarımız, halka açık Akışı, ücretli içerik yerine sivil içeriği tercih edecek şekilde manipüle etmez.",
    "de": "Unsere Algorithmen manipulieren den öffentlichen Feed nicht, um bezahlte Inhalte gegenüber zivilen Inhalten zu bevorzugen."
  },
  "Ne përdorim skedarë thelbësorë (Cookies) për të mbajtur sesionin tuaj të kyçur dhe për të mbajtur mend preferencat tuaja lokale (psh. Tema Dark/Light, Gjuha).": {
    "sq": "Ne përdorim skedarë thelbësorë (Cookies) për të mbajtur sesionin tuaj të kyçur dhe për të mbajtur mend preferencat tuaja lokale (psh. Tema Dark/Light, Gjuha).",
    "en": "We use essential files (Cookies) to keep your session locked and to remember your local preferences (eg Dark/Light Theme, Language).",
    "bs": "Koristimo osnovne fajlove (kolačiće) da zadržimo vašu sesiju zaključanom i da zapamtimo vaše lokalne postavke (npr. Tamna/Svetla tema, Jezik).",
    "sr": "Користимо основне фајлове (колачиће) да задржимо вашу сесију закључаном и да запамтимо ваше локалне поставке (нпр. тамна/светла тема, језик).",
    "tr": "Oturumunuzu kilitli tutmak ve yerel tercihlerinizi (örn. Koyu/Açık Tema, Dil) hatırlamak için temel dosyaları (Çerezler) kullanırız.",
    "de": "Wir verwenden wichtige Dateien (Cookies), um Ihre Sitzung gesperrt zu halten und Ihre lokalen Präferenzen zu speichern (z. B. dunkles/helles Design, Sprache)."
  },
