  "për këtë vit. \n              Shtypni dhe lëvizni rrëshqitësit më poshtë për të ndarë buxhetin në 5 sektorët kryesorë sipas prioriteteve tuaja. \n              Pasi totali i shpërndarë të jetë saktësisht 1,000,000 €, klikoni \"Dërgo Propozimin\".": {
    "sq": "për këtë vit. \n              Shtypni dhe lëvizni rrëshqitësit më poshtë për të ndarë buxhetin në 5 sektorët kryesorë sipas prioriteteve tuaja. \n              Pasi totali i shpërndarë të jetë saktësisht 1,000,000 €, klikoni \"Dërgo Propozimin\".",
    "en": "for this year. \n              Click and move the sliders below to divide the budget into the top 5 sectors according to your priorities. \n              Once the distributed total is exactly €1,000,000, click \"Submit Proposal\".",
    "bs": "za ovu godinu. \n              Kliknite i pomjerite klizače ispod da podijelite budžet na prvih 5 sektora prema vašim prioritetima. \n              Kada raspodijeljeni iznos bude tačno 1.000.000 €, kliknite na \"Pošalji prijedlog\".",
    "sr": "за ову годину. \n              Кликните и померите клизаче испод да бисте поделили буџет на првих 5 сектора према вашим приоритетима. \n              Када расподељени износ буде тачно 1.000.000 евра, кликните на „Пошаљи предлог“.",
    "tr": "bu yıl için. \n              Bütçeyi önceliklerinize göre ilk 5 sektöre bölmek için aşağıdaki kaydırıcıları tıklayıp hareket ettirin. \n              Dağıtılan toplam tutar tam olarak 1.000.000 € olduğunda, \"Teklifi Gönder\"e tıklayın.",
    "de": "für dieses Jahr. \n              Klicken und verschieben Sie die Schieberegler unten, um das Budget entsprechend Ihren Prioritäten in die fünf wichtigsten Sektoren aufzuteilen. \n              Sobald die ausgeschüttete Summe genau 1.000.000 € beträgt, klicken Sie auf „Vorschlag einreichen“."
  },
