  "Platforma jonë tashmë mbështet mbledhjen e fondeve për qytetarët që janë në nevojë ekstreme financiare apo shëndetësore. Shihni se si mund të kontribuoni.": {
    "sq": "Platforma jonë tashmë mbështet mbledhjen e fondeve për qytetarët që janë në nevojë ekstreme financiare apo shëndetësore. Shihni se si mund të kontribuoni.",
    "en": "Our platform already supports fundraising for citizens who are in extreme financial or health need. See how you can contribute.",
    "bs": "Naša platforma već podržava prikupljanje sredstava za građane koji su u ekstremnim finansijskim ili zdravstvenim potrebama. Pogledajte kako možete doprinijeti.",
    "sr": "Наша платформа већ подржава прикупљање средстава за грађане који су у екстремним финансијским или здравственим потребама. Погледајте како можете да допринесете.",
    "tr": "Platformumuz halihazırda aşırı mali veya sağlık ihtiyacı olan vatandaşlar için bağış toplamayı desteklemektedir. Nasıl katkıda bulunabileceğinizi görün.",
    "de": "Unsere Plattform unterstützt bereits das Sammeln von Spenden für Bürger, die sich in extremer finanzieller oder gesundheitlicher Not befinden. Sehen Sie, wie Sie dazu beitragen können."
  },
