  "Vota juaj është thelbësore për vendimet tona. Merrni pjesë në sondazhet aktive, ndani mendimin tuaj mbi politikat e ardhshme dhe ndihmoni në përmirësimin e qytetit tonë me anë të demokracisë së drejtpërdrejtë. Të gjitha votimet janë plotësisht anonime dhe të sigurta (enkriptim SSL 256-bit).": {
    "sq": "Vota juaj është thelbësore për vendimet tona. Merrni pjesë në sondazhet aktive, ndani mendimin tuaj mbi politikat e ardhshme dhe ndihmoni në përmirësimin e qytetit tonë me anë të demokracisë së drejtpërdrejtë. Të gjitha votimet janë plotësisht anonime dhe të sigurta (enkriptim SSL 256-bit).",
    "en": "Your vote is essential to our decisions. Take part in active polls, share your opinion on future policies and help improve our city through direct democracy. All votes are completely anonymous and secure (256-bit SSL encryption).",
    "bs": "Vaš glas je bitan za naše odluke. Učestvujte u aktivnim anketama, podijelite svoje mišljenje o budućim politikama i pomozite poboljšanju našeg grada kroz direktnu demokratiju. Svi glasovi su potpuno anonimni i sigurni (256-bitna SSL enkripcija).",
    "sr": "Ваш глас је од суштинског значаја за наше одлуке. Учествујте у активним анкетама, поделите своје мишљење о будућим политикама и помозите да унапредимо наш град кроз директну демократију. Сви гласови су потпуно анонимни и безбедни (256-битна ССЛ енкрипција).",
    "tr": "Oyunuz kararlarımız için çok önemli. Aktif anketlere katılın, gelecekteki politikalar hakkındaki görüşlerinizi paylaşın ve doğrudan demokrasi yoluyla şehrimizin gelişmesine yardımcı olun. Tüm oylar tamamen anonim ve güvenlidir (256 bit SSL şifreleme).",
    "de": "Ihre Stimme ist für unsere Entscheidungen von entscheidender Bedeutung. Nehmen Sie an aktiven Umfragen teil, teilen Sie Ihre Meinung zu künftigen politischen Maßnahmen und helfen Sie, unsere Stadt durch direkte Demokratie zu verbessern. Alle Abstimmungen erfolgen völlig anonym und sicher (256-Bit-SSL-Verschlüsselung)."
  },
