  "Sistemi ka gjetur një raportim që keni filluar më herët por nuk e keni përfunduar. Dëshironi të vazhdoni aty ku keni mbetur, apo të filloni një raportim të ri?": {
    "sq": "Sistemi ka gjetur një raportim që keni filluar më herët por nuk e keni përfunduar. Dëshironi të vazhdoni aty ku keni mbetur, apo të filloni një raportim të ri?",
    "en": "The system has found a report that you started earlier but did not complete. Do you want to continue where you left off, or start a new report?",
    "bs": "Sistem je pronašao izvještaj koji ste ranije započeli, ali niste dovršili. Želite li nastaviti tamo gdje ste stali ili započeti novi izvještaj?",
    "sr": "Систем је пронашао извештај који сте раније започели, али нисте довршили. Да ли желите да наставите тамо где сте стали или да започнете нови извештај?",
    "tr": "Sistem, daha önce başlattığınız ancak tamamlamadığınız bir rapor buldu. Kaldığınız yerden devam etmek mi yoksa yeni bir rapora mı başlamak istiyorsunuz?",
    "de": "Das System hat einen Bericht gefunden, den Sie zuvor gestartet, aber nicht abgeschlossen haben. Möchten Sie dort weitermachen, wo Sie aufgehört haben, oder einen neuen Bericht beginnen?"
  },
