  "ZëriYT është portal nga komuniteti, për komunitetin. Të gjitha të dhënat janë të sigurta dhe mund të zgjidhni të mbeteni anonim gjatë postimeve tuaja.": {
    "sq": "ZëriYT është portal nga komuniteti, për komunitetin. Të gjitha të dhënat janë të sigurta dhe mund të zgjidhni të mbeteni anonim gjatë postimeve tuaja.",
    "en": "ZëriYT is a portal by the community, for the community. All data is secure and you can choose to remain anonymous during your posts.",
    "bs": "ZëriYT je portal zajednice, za zajednicu. Svi podaci su sigurni i možete odabrati da ostanete anonimni tokom svojih objava.",
    "sr": "ЗериИТ је портал заједнице, за заједницу. Сви подаци су безбедни и можете изабрати да останете анонимни током својих објава.",
    "tr": "ZëriYT, topluluk tarafından topluluk için hazırlanmış bir portaldır. Tüm veriler güvendedir ve gönderileriniz sırasında anonim kalmayı seçebilirsiniz.",
    "de": "ZëriYT ist ein Portal von der Community für die Community. Alle Daten sind sicher und Sie können bei Ihren Beiträgen anonym bleiben."
  },
