  "Reparti i Posaçëm i Menaxhimit të Agentëve": {
    "sq": "Reparti i Posaçëm i Menaxhimit të Agentëve",
    "en": "Special Agent Management Department",
    "bs": "Odeljenje za upravljanje specijalnim agentima",
    "sr": "Одељење за управљање специјалним агентима",
    "tr": "Özel Acente Yönetimi Departmanı",
    "de": "Abteilung für Spezialagentenmanagement"
  },
  "Krijoni, editoni dhe delegoni qasje të kufizuar për punëtorët agentë. Caktoni ata vetëm për aprovim të raportimeve, donacioneve apo reklamave, dhe kontrolloni çdo veprim të tyre në kohë reale.": {
    "sq": "Krijoni, editoni dhe delegoni qasje të kufizuar për punëtorët agentë. Caktoni ata vetëm për aprovim të raportimeve, donacioneve apo reklamave, dhe kontrolloni çdo veprim të tyre në kohë reale.",
    "en": "Create, edit and delegate limited access to agent workers. Designate them only for approving reports, donations or ads, and monitor their every action in real time.",
    "bs": "Kreirajte, uređujte i delegirajte ograničeni pristup agentskim radnicima. Odredite ih samo za odobravanje izvještaja, donacija ili oglasa i pratite svaku njihovu akciju u realnom vremenu.",
    "sr": "Креирајте, уређујте и делегирајте ограничени приступ радницима агента. Одредите их само за одобравање извештаја, донација или огласа и пратите сваку њихову акцију у реалном времену.",
    "tr": "Temsilci çalışanlara sınırlı erişim oluşturun, düzenleyin ve yetki verin. Onları yalnızca raporları, bağışları veya reklamları onaylamak için atayın ve her eylemlerini gerçek zamanlı olarak izleyin.",
    "de": "Erstellen, bearbeiten und delegieren Sie eingeschränkten Zugriff an Agentenmitarbeiter. Benennen Sie sie nur für die Genehmigung von Berichten, Spenden oder Anzeigen und überwachen Sie jede ihrer Aktionen in Echtzeit."
  },
