    "sr": "Kur një qytetar zgjedh komunën e tij në faqe (psh. Prishtinë), sistemi automatikisht kërkon nëse ka ndonjë reklamë të dedikuar për Prishtinë. Nëse po, shfaqet reklama e Prishtinës. Nëse jo, shfaqen reklamat Nacionale, ose kjo hapësirë e lirë me numrin tuaj të telefonit.",
    "tr": "Kur një qytetar zgjedh komunën e tij në faqe (psh. Prishtinë), sistemi automatikisht kërkon nëse ka ndonjë reklamë të dedikuar për Prishtinë. Nëse po, shfaqet reklama e Prishtinës. Nëse jo, shfaqen reklamat Nacionale, ose kjo hapësirë e lirë me numrin tuaj të telefonit.",
