  "Ligji Nr. 06/L-082 për Mbrojtjen e të Dhënave Personale në Kosovë kërkon pëlqimin tuaj të qartë dhe të lirë për çdo Cookies jo-esenciale dhe çdo gjurmim të lokacionit.": {
    "sq": "Ligji Nr. 06/L-082 për Mbrojtjen e të Dhënave Personale në Kosovë kërkon pëlqimin tuaj të qartë dhe të lirë për çdo Cookies jo-esenciale dhe çdo gjurmim të lokacionit.",
    "en": "Law No. 06/L-082 on Personal Data Protection in Kosovo requires your clear and free consent for every non-essential cookie and any location tracking.",
    "bs": "Zakon br. 06/L-082 o zaštiti ličnih podataka na Kosovu zahtijeva vaš jasan i slobodan pristanak za svaki neesencijalni kolačić i svako praćenje lokacije.",
    "sr": "Закон бр. 06/L-082 о заштити личних података на Косову захтева ваш јасан и слободан пристанак за сваки неесенцијални колачић и свако праћење локације.",
    "tr": "Kanun No. 06/L-082 Kişisel Verilerin Korunması, her esansiyel olmayan çerez ve her konum takibi için açık ve özgür rızanızı gerektirir.",
    "de": "Gesetz Nr. 06/L-082 zum Schutz personenbezogener Daten im Kosovo verlangt Ihre klare und freiwillige Einwilligung für jedes nicht notwendige Cookie und jede Standortverfolgung."
  },
  "Ne përdorim Cookies dhe teknologji të ngjashme për të mbajtur sesionin tuaj, për të matur sa të përdoret platforma dhe për të shfaqur reklama.": {
    "sq": "Ne përdorim Cookies dhe teknologji të ngjashme për të mbajtur sesionin tuaj, për të matur sa të përdoret platforma dhe për të shfaqur reklama.",
    "en": "We use cookies and similar technologies to keep your session, measure platform usage and show advertising.",
    "bs": "Koristimo kolačiće i slične tehnologije za održavanje sesije, mjerenje korištenja platforme i prikazivanje reklama.",
    "sr": "Користимо колачиће и сличне технологије за одржавање сесије, мерење коришћења платформе и приказивање реклама.",
    "tr": "Çerezleri ve benzeri teknolojileri oturumunuzu sürdürmek, platform kullanımını ölçmek ve reklam göstermek için kullanıyoruz.",
    "de": "Wir verwenden Cookies und ähnliche Technologien, um Ihre Sitzung zu erhalten, die Nutzung zu messen und Werbung anzuzeigen."
  },
  "Pa pëlqimin tuaj, asnjë Cookies analitike apo marketingu nuk ngarkohet.": {
    "sq": "Pa pëlqimin tuaj, asnjë Cookies analitike apo marketingu nuk ngarkohet.",
    "en": "Without your consent, no analytics or marketing cookie is loaded.",
    "bs": "Bez vašeg pristanka nijedan analitički ni marketinški kolačić se ne učitava.",
    "sr": "Без вашег пристанка ниједан аналитички ни маркетиншки колачић се не учитава.",
    "tr": "Onayınız olmadan hiçbir analitik veya pazarlama çerezi yüklenmez.",
    "de": "Ohne Ihre Einwilligung wird kein Analyse- oder Marketing-Cookie geladen."
  },
