    "sr": "Sistemi i reklamave AdminAds mat performancën e faqeve të sponsorizuara nga komunat dhe institucionet. Aktivizohet vetëm pas pëlqimit tuaj, mund të çaktivizohet në çdo kohë dhe nuk lidhet me të dhënat shëndetësore ose me regjistrin e raporteve. Baza ligjore: pëlqimi juaj.",
    "tr": "Sistemi i reklamave AdminAds mat performancën e faqeve të sponsorizuara nga komunat dhe institucionet. Aktivizohet vetëm pas pëlqimit tuaj, mund të çaktivizohet në çdo kohë dhe nuk lidhet me të dhënat shëndetësore ose me regjistrin e raporteve. Baza ligjore: pëlqimi juaj.",
